/* Root ID Function SQL for MJ: AI Agent Sessions.LastSessionID */
-- ============================================================
-- PostgreSQL Generated SQL for Entity: MJ: AI Agent Sessions
-- Item: fnAIAgentSessionLastSessionID_GetRootID
-- Generated at: 2026-07-10T21:00:57.728Z
-- ============================================================

------------------------------------------------------------
----- ROOT ID FUNCTION FOR: AIAgentSession.LastSessionID
------------------------------------------------------------
CREATE OR REPLACE FUNCTION ${flyway:defaultSchema}."fn_ai_agent_session_last_session_id_get_root_id"(
    p_record_id UUID,
    p_parent_id UUID
) RETURNS UUID AS $$
    WITH RECURSIVE cte_root_parent AS (
        -- Anchor: Start from p_parent_id if not null, otherwise start from p_record_id
        SELECT
            "ID",
            "LastSessionID",
            "ID" AS root_parent_id,
            0 AS depth
        FROM
            ${flyway:defaultSchema}."AIAgentSession"
        WHERE
            "ID" = COALESCE(p_parent_id, p_record_id)

        UNION ALL

        -- Recursive: Keep going up the hierarchy
        SELECT
            c."ID",
            c."LastSessionID",
            c."ID" AS root_parent_id,
            p.depth + 1 AS depth
        FROM
            ${flyway:defaultSchema}."AIAgentSession" c
        INNER JOIN
            cte_root_parent p ON c."ID" = p."LastSessionID"
        WHERE
            p.depth < 100  -- Prevent infinite loops
    )
    SELECT root_parent_id
    FROM cte_root_parent
    WHERE "LastSessionID" IS NULL
    ORDER BY root_parent_id
    LIMIT 1;
$$ LANGUAGE sql STABLE;

